<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Notification\Message\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Notification\Message\Domain\ValueObject\MessageTargetVO;

trait MessageTargetAccessor
{
    private MessageTargetVO $_target;
    public function getTarget(): string
    {
        return $this->_target->value();
    }
    public function target(): MessageTargetVO
    {
        return $this->_target;
    }
    public function isTargetChanged(?self $original = null): bool
    {
        return !$this->_target->equals($original?->_target);
    }
    public function withTarget(MessageTargetVO|string $target): self
    {
        $copy = clone $this;
        $copy->_target = MessageTargetVO::from($target);
        return $copy;
    }
}
